  "claim": {
    "component_id": "C057",
    "value": "Deployment safety requires confirmation and monitored rollout beyond boundary localization.",
    "scope": "Limit on treating a localized association as establishing deployment safety; confirmation criteria are unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P034",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P034 explicitly places deployment safety under a confirmation and monitored rollout requirement beyond the localized association."
    }
  },
  "signal_basis": {
    "component_id": "C057_SIGNAL",
    "value": "Repeated, uncertainty-aware midpoint classifications shrink the candidate transition interval to a boundary, or leave an unresolved interval. With valid endpoints, comparable trials and a persistent single transition, localization establishes a revision association under tested conditions.",
    "scope": "The defined increase in the probability of exports exceeding one hour under comparable workloads; no deployment safety conclusion follows from localization alone.",
